// The CUFC/USG coding tree — Slava's 01–44 structure, as typed data.
//
// Ported verbatim from Victor's workbook, transcribed to
// outputs/budget-automation/coding-tree/{code-tree,mirror-rules}.json. Every node here is a
// fact about what the workbook says, not a fact about what should be posted — see
// outputs/budget-automation/00-verified-findings.md §1 & §3 before trusting a leaf: 206 of
// 805 rows are `provenance: "suggested_placeholder"` (invented by the workbook author, never
// approved), and the tree's leaves mostly describe programmes ClubOS does not sell.
//
// `unit_price_ex_gst` and `budget_ex_gst` are dropped from the port on purpose: every row in
// the source workbook carries them empty/zero (verified — "this workbook is a structure, not
// a budget"). Carrying a fake `"0"` budget field into typed data invites someone to render it
// as a real number. There is no budget data. Do not add one here — Phase 0 is a human
// document, not this file.
//
// No DB, no network. Tested by script/test-accounting-codes.ts (npx tsx script/test-accounting-codes.ts).

// ── The code tree ────────────────────────────────────────────────────────────

export type AcctCodeType = "income" | "expense";

/** Verbatim from the workbook's own `Source Basis` column — never re-labelled into an
 *  invented taxonomy. "original_note" = Slava's own hand-drawn structure. "suggested_placeholder"
 *  = invented by the workbook author; treat as a proposal, not an approved code. */
export type AcctCodeProvenance =
  | "original_note"
  | "expanded_from_original_note"
  | "suggested_placeholder";

export interface AcctCodeNode {
  code: string;
  level: 1 | 2 | 3 | 4 | 5;
  type: AcctCodeType;
  parentCode: string | null;
  rootCode: string;
  parentCategory: string;
  name: string;
  period: string | null;
  invoiceTo: string | null;
  invoiceDescription: string | null;
  basis: string | null;
  owner: string | null;
  status: string;
  notes: string | null;
  /** A level-5 templated invoice row, e.g. "01-01-01-T1-[PlayerName]" — a shape for
   *  generating per-invoice codes, not a distinct code anyone posts to directly. */
  isInvoiceStage: boolean;
  isTemplate: boolean;
  provenance: AcctCodeProvenance;
}

