export const ACCT_CODES_BY_CODE: Record<string, AcctCodeNode> = Object.fromEntries(
  ACCT_CODE_TREE.map((node) => [node.code, node]),
);

/** Direct children of `parentCode` (one level down), in tree order. */
export function childrenOf(parentCode: string): AcctCodeNode[] {
  return ACCT_CODE_TREE.filter((node) => node.parentCode === parentCode);
}

/** Every code whose `parent_code` is non-null must resolve to a code in the tree, and every
 *  level-1 code must have a null parent. Returns an empty array when the tree is sound —
 *  see script/test-accounting-codes.ts, the single highest-value test in this build. */
export function validateCodeTree(nodes: AcctCodeNode[] = ACCT_CODE_TREE): string[] {
  const errors: string[] = [];
  for (const node of nodes) {
    if (node.level === 1) {
      if (node.parentCode !== null) {
        errors.push(`${node.code}: level-1 code must have a null parent_code`);
      }
      continue;
    }
    if (node.parentCode === null) {
      errors.push(`${node.code}: level-${node.level} code has a null parent_code`);
      continue;
    }
    if (!ACCT_CODES_BY_CODE[node.parentCode]) {
      errors.push(`${node.code}: parent_code "${node.parentCode}" does not exist in the tree`);
    }
  }
  return errors;
}

// ── Mirror rules ─────────────────────────────────────────────────────────────
//
// Slava's rule "income code + 30 = expense code" is documented but WRONG as arithmetic — it
// only holds for 01–12 → 31–42. Applying `+30` blindly collides:
//   13 Donations      + 30 = 43  →  43 is CUFC First Team    (43 has no income code at all)
//   14 Reimbursement  + 30 = 44  →  44 is South Island United (same)
// See outputs/budget-automation/coding-tree/mirror-rules.json (the authority this is ported
// from) and 00-verified-findings.md §2.

export interface MirrorRuleEntry {
  incomeCode: string;
  income: string;
  expenseCode: string;
  expense: string;
}

/** The ONLY codes where income+expense actually mirror: 01–12 → 31–42. Do not derive this by
 *  arithmetic — use `expenseCodeFor()`, which consults this table and nothing else. */
export const MIRRORED_CODES: MirrorRuleEntry[] = [
  { incomeCode: "01", income: "Academy Programs", expenseCode: "31", expense: "Academy Cost of Sales" },
  { incomeCode: "02", income: "Tournament Registrations", expenseCode: "32", expense: "Tournaments" },
  { incomeCode: "03", income: "Holiday Camps", expenseCode: "33", expense: "Holiday Camps" },
  { incomeCode: "04", income: "MFL", expenseCode: "34", expense: "MFL" },
  { incomeCode: "05", income: "Merchandising", expenseCode: "35", expense: "Merchandising" },
  { incomeCode: "06", income: "United Prints", expenseCode: "36", expense: "United Prints" },
  { incomeCode: "07", income: "Field / Facility Hire", expenseCode: "37", expense: "Field Hire / Facility Costs (USC)" },
  { incomeCode: "08", income: "Sponsorship", expenseCode: "38", expense: "Sponsorship" },
  { incomeCode: "09", income: "Grant Funding", expenseCode: "39", expense: "Grant Funding" },
  { incomeCode: "10", income: "Fundraising", expenseCode: "40", expense: "Fundraising" },
  { incomeCode: "11", income: "Residence Program", expenseCode: "41", expense: "Residence Program" },
  { incomeCode: "12", income: "Media Company", expenseCode: "42", expense: "Media Company" },];

/** 13 Donations, 14 Reimbursement, 15 Other Income — Slava wrote "no expenses here" against
 *  all three. `expenseCodeFor()` returns null for these, never a guessed code. */
export const INCOME_ONLY_CODES: Record<string, string> = {
  "13": "Donations",
  "14": "Reimbursement",
  "15": "Other Income",};

/** 43 CUFC First Team, 44 South Island United — pure cost centres with no income code
 *  anywhere in 01–15. First Team/SIU revenue has no home in the chart yet (see
 *  00-verified-findings.md §7 question 2 — a human decision, not this file's to make). */
export const COST_CENTRES_NO_INCOME: Record<string, string> = {
  "43": "CUFC First Team",
  "44": "South Island United",};

/** 21 Staff Salary, 22 Marketing, 23 Operating Expenses — shared overheads, mirrored by
 *  nothing. */
export const SHARED_OVERHEAD_CODES: Record<string, string> = {
  "21": "Staff Salary",
  "22": "Marketing incl. Football in Schools",
  "23": "Operating Expenses",};

/** The expense code that mirrors a given income code, or `null` when there isn't one —
 *  NEVER `income + 30`. Only 01–12 mirror to 31–42; every other income code (13/14/15, or
 *  anything outside 01–15) returns null. Consult this table, never arithmetic. */
export function expenseCodeFor(incomeCode: string): string | null {
  const rule = MIRRORED_CODES.find((r) => r.incomeCode === incomeCode);
  return rule ? rule.expenseCode : null;
}
